// `colab-comfy cache ls | prune [--keep-referenced]` (PLAN §6.2): inspect and clean <film dir>/.colab-comfy/cache.
//
// "Referenced" = the entry is the winner (`winner.cacheKey`) of a run record that the film's lock lists under a
// node's produces (the lock pins the record's sha; the record names the cache key). Losing candidates and
// clips of superseded prompts are unreferenced. Records are read, never written; the lock is never touched.
//
// Decision (PLAN left bare `prune` open): a cached clip cost real CU and can only be regenerated by spending again,
// so `prune` without `--keep-referenced` deletes EVERYTHING and therefore also requires `--yes`. Pruning while a
// session might be alive (active.json present) is refused: a download could be in flight.

import { existsSync, readFileSync, readdirSync, rmSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { parse as parseYaml } from "yaml";
import { STATE_DIR, type CacheMeta } from "./cache.ts";
import { ColabComfyError, EXIT, invalid } from "./errors.ts";
import { activePath, stateDir } from "./ledger.ts";

export interface CacheEntry {
  key: string;
  dir: string;
  /** false: clip.mp4 or meta.json missing (a leftover of a failed download); never a usable hit. */
  complete: boolean;
  bytes: number;
  node: string | null;
  candidate: number | null;
  seed: number | null;
  session: string | null;
  downloadedAt: string | null;
  referencedBy: string[];
}

function dirBytes(dir: string): number {
  let total = 0;
  for (const name of readdirSync(dir)) {
    const st = statSync(join(dir, name));
    total += st.isDirectory() ? dirBytes(join(dir, name)) : st.size;
  }
  return total;
}

/** cache key -> lock node ids whose run record names it as winner. */
export function referencedKeys(lockPath: string): Map<string, string[]> {
  const out = new Map<string, string[]>();
  if (!existsSync(lockPath)) return out;
  let lock: { nodes?: Record<string, { produces?: Record<string, { path?: string }> }> } | null;
  try {
    lock = parseYaml(readFileSync(lockPath, "utf8"));
  } catch (err) {
    throw new ColabComfyError(EXIT.io, [{ code: "io", message: `cannot parse ${lockPath}: ${(err as Error).message}`, hint: "refusing to decide what is referenced; nothing was deleted" }]);
  }
  const base = dirname(lockPath);
  for (const [id, node] of Object.entries(lock?.nodes ?? {})) {
    for (const p of Object.values(node.produces ?? {})) {
      if (typeof p?.path !== "string" || !p.path.endsWith(".json")) continue;
      try {
        const rec = JSON.parse(readFileSync(resolve(base, p.path), "utf8"));
        if (rec?.schema !== "colab-comfy/run-record@1") continue;
        const key = rec.winner?.cacheKey;
        if (typeof key === "string") out.set(key, [...(out.get(key) ?? []), id]);
      } catch {
        // a missing/unreadable record means the node is not (yet) materialized: it references nothing
      }
    }
  }
  return out;
}

export function listCache(baseDir: string, lockPath: string): CacheEntry[] {
  const root = join(baseDir, STATE_DIR, "cache");
  if (!existsSync(root)) return [];
  const refs = referencedKeys(lockPath);
  const entries: CacheEntry[] = [];
  for (const k2 of readdirSync(root).sort()) {
    const k2dir = join(root, k2);
    if (!statSync(k2dir).isDirectory()) continue;
    for (const key of readdirSync(k2dir).sort()) {
      const dir = join(k2dir, key);
      if (!statSync(dir).isDirectory()) continue;
      const complete = existsSync(join(dir, "clip.mp4")) && existsSync(join(dir, "meta.json"));
      let meta: Partial<CacheMeta> = {};
      try {
        meta = JSON.parse(readFileSync(join(dir, "meta.json"), "utf8"));
      } catch {
        // incomplete entry: listed as such
      }
      entries.push({
        key,
        dir,
        complete,
        bytes: dirBytes(dir),
        node: meta.node ?? null,
        candidate: meta.candidate ?? null,
        seed: meta.seed ?? null,
        session: meta.session ?? null,
        downloadedAt: meta.downloadedAt ?? null,
        referencedBy: refs.get(key) ?? [],
      });
    }
  }
  return entries;
}

export interface PruneOptions {
  baseDir: string;
  lockPath: string;
  keepReferenced: boolean;
  yes: boolean;
  dryRun: boolean;
}

export interface PruneReport {
  removed: CacheEntry[];
  kept: CacheEntry[];
  freedBytes: number;
  dryRun: boolean;
}

export function pruneCache(o: PruneOptions): PruneReport {
  if (!o.keepReferenced && !o.yes && !o.dryRun) {
    throw new ColabComfyError(EXIT.needsConfirmation, [
      { code: "needs-confirmation", message: "prune without --keep-referenced deletes every cached clip; each one cost CU to generate", hint: "use --keep-referenced, or add --yes (or --dry-run to preview)" },
    ]);
  }
  if (existsSync(activePath(stateDir(o.baseDir)))) {
    throw new ColabComfyError(EXIT.invalidInput, [invalid("a Colab session may be active (.colab-comfy/active.json exists): refusing to prune", undefined, "run `colab-comfy reap` first")]);
  }
  const all = listCache(o.baseDir, o.lockPath);
  // Incomplete entries are never hits, so they go even with --keep-referenced.
  const doomed = (e: CacheEntry) => !e.complete || !o.keepReferenced || e.referencedBy.length === 0;
  const removed = all.filter(doomed);
  const kept = all.filter((e) => !doomed(e));
  if (!o.dryRun) for (const e of removed) rmSync(e.dir, { recursive: true, force: true });
  return { removed, kept, freedBytes: removed.reduce((s, e) => s + e.bytes, 0), dryRun: o.dryRun };
}

const mib = (b: number) => `${(b / 1048576).toFixed(1)} MiB`;

export function formatCacheList(entries: CacheEntry[]): string {
  if (entries.length === 0) return "cache is empty";
  const lines = entries.map(
    (e) => `${e.key.slice(0, 12)}  ${e.complete ? "ok        " : "INCOMPLETE"}  ${mib(e.bytes).padStart(10)}  ${e.node ?? "?"}#${e.candidate ?? "?"} seed ${e.seed ?? "?"}  ${e.referencedBy.length ? `referenced by ${e.referencedBy.join(",")}` : "unreferenced"}`,
  );
  return [...lines, `${entries.length} entr${entries.length === 1 ? "y" : "ies"}, ${mib(entries.reduce((s, e) => s + e.bytes, 0))}`].join("\n");
}

export function formatPrune(r: PruneReport): string {
  return `${r.dryRun ? "would remove" : "removed"} ${r.removed.length} entr${r.removed.length === 1 ? "y" : "ies"} (${mib(r.freedBytes)}); kept ${r.kept.length} referenced`;
}
